def count_solutions():
    solutions = []
    for n in range(2, 200):
        if n % 2 == 0 or n % 3 == 0:
            continue
        is_valid = True
        for a in range(n // 3 + 1, n // 2 + 1):
            k = n - 2 * a
            if k == 0:
                # n is odd, so k is never 0.
                continue
            import math
            val = math.comb(a-1, k-1)
            if val % k != 0:
                is_valid = False
                break
        if is_valid:
            solutions.append(n)
    return solutions

print(count_solutions())

